// === Tab: extrude-polyline ===
/**
 * Based on Matt DesLauriers work https://github.com/mattdesl/extrude-polyline/tree/master
 * Adapted and simplified for P5. Under MIT License.
 **/

// Get perpendicular vector
let getNormal = (dir) => {
  return createVector(-dir.y, dir.x)
}

// Get direction vector from points
let getDirection = (a, b) => {
  let out = p5.Vector.sub(a, b)
  out.normalize()
  return out
}

let scaleAndAdd = (a, b, scale) => {
  return createVector(a.x + b.x * scale, a.y + b.y * scale)
}

let extrusions = (positions, point, normal, scale) => {
  // Next two points to end our segment
  tmp = scaleAndAdd(point, normal, -scale)
  positions.push(tmp.copy())

  tmp = scaleAndAdd(point, normal, scale)
  positions.push(tmp.copy())
}

// To be translated into P5 vectors and use standard vector operations
let tmp = new p5.Vector()
let capEnd = new p5.Vector()
let lineA = new p5.Vector()
let lineB = new p5.Vector()
let tangent = new p5.Vector()
let miter = new p5.Vector()

class Stroke {
  static get Join() {
    return {
      MITER: "miter",
      BEVEL: "bevel",
    }
  }

  static get Cap() {
    return {
      // BUTT: "butt",
      SQUARE: "square",
      PROJECT: "project",
    }
  }

  constructor(opts = {}) {
    this.miterLimit = opts.miterLimit || 10
    this.thickness = opts.thickness || 1
    this.join = opts.join || Stroke.Join.MITER
    this.cap = opts.cap || Stroke.Cap.SQUARE
    this._normal = null
    this._lastFlip = -1
    this._started = false
    this.closed = opts.closed || false
  }

  build(points, thicknessFn) {
    let complex = {
      positions: [],
      cells: [],
    }
    thicknessFn = thicknessFn || (() => this.thickness)
    // Convert points to p5.vectors if not already
    points = points.map((p) => {
      if (p instanceof p5.Vector) return p
      return createVector(p[0], p[1])
    })

    if (points.length <= 1) return complex

    let total = points.length

    // Clear flags
    this._lastFlip = -1
    this._started = false
    this._normal = null

    // Join each segment
    for (let i = 1, count = 0; i < total; i++) {
      let last = points[i - 1]
      let cur = points[i]
      let next = i < points.length - 1 ? points[i + 1] : null
      let thickness = thicknessFn(cur, i, points)
      let amt = this._seg(complex, count, last, cur, next, thickness / 2)
      count += amt
    }

    // Add closing segment if closed
    if (this.closed) {
      let last = complex.positions.length - 1
      complex.cells.push([last - 1, last, 0])
      complex.cells.push([last, 0, 1])
    }

    return complex
  }

  _seg(complex, index, last, cur, next, halfThick) {
    let count = 0
    let cells = complex.cells
    let positions = complex.positions
    let capProject = this.cap === Stroke.Cap.PROJECT
    let joinBevel = this.join === Stroke.Join.BEVEL

    // Get unit direction of line

    // getDirection(lineA, cur, last)
    lineA = getDirection(cur, last)

    // If we don't yet have a normal from previous join, compute based on line start - end
    if (!this._normal) {
      this._normal = getNormal(lineA)
    }

    // If we haven't started yet, add the first two points
    if (!this._started) {
      this._started = true

      // If the end cap is type "project", we can just push the vertices out a bit
      if (capProject) {
        capEnd = scaleAndAdd(last, lineA, -halfThick)
        last = capEnd
      }

      extrusions(positions, last, this._normal, halfThick)
    }

    cells.push([index + 0, index + 1, index + 2])

    // Now determine the type of join with next segment
    if (!next) {
      // No next segment, simple extrusion
      // Now reset normal to finish cap
      this._normal = getNormal(lineA)

      // Push project end cap out a bit
      if (capProject) {
        capEnd = scaleAndAdd(cur, lineA, halfThick)
        cur = capEnd
      }

      extrusions(positions, cur, this._normal, halfThick)
      cells.push(
        this._lastFlip === 1
          ? [index, index + 2, index + 3]
          : [index + 2, index + 1, index + 3]
      )

      count += 2
    } else {
      // We have a next segment, start with miter

      // Get unit dir of next line
      lineB = getDirection(next, cur)

      tangent = p5.Vector.add(lineA, lineB).normalize()

      // Get miter as a unit vector
      miter = getNormal(tangent)
      tmp = getNormal(lineA)

      // Get the necessary length of our miter
      let miterLen = halfThick / miter.dot(tmp)

      // Get orientation
      let flip = tangent.dot(this._normal) < 0 ? -1 : 1

      let bevel = joinBevel
      if (!bevel && this.join === Stroke.Join.MITER) {
        let limit = miterLen / halfThick
        if (limit > this.miterLimit) bevel = true
      }

      if (bevel) {
        // Next two points in our first segment
        tmp = scaleAndAdd(cur, this._normal, -halfThick * flip)
        positions.push(tmp.copy())
        tmp = scaleAndAdd(cur, miter, miterLen * flip)
        positions.push(tmp.copy())

        cells.push(
          this._lastFlip !== -flip
            ? [index, index + 2, index + 3]
            : [index + 2, index + 1, index + 3]
        )

        // Now add the bevel triangle
        cells.push([index + 2, index + 3, index + 4])

        tmp = getNormal(lineB)
        this._normal = tmp.copy() // Store normal for next round

        tmp = scaleAndAdd(cur, tmp, -halfThick * flip)
        positions.push(tmp.copy())

        count += 3
      } else {
        // Miter
        // Next two points for our miter join
        extrusions(positions, cur, miter, miterLen)
        cells.push(
          this._lastFlip === 1
            ? [index, index + 2, index + 3]
            : [index + 2, index + 1, index + 3]
        )

        flip = -1

        // The miter is now the normal for our next join
        this._normal = miter.copy()
        count += 2
      }
      this._lastFlip = flip
    }
    return count
  }
}


