// Shrooooms
// For the #WCCChallenge << Fungi >> (join the discord! https://discord.gg/S8c7qcjw2b)

/*
 * This week was all about randomness and noise, mixed together to show some controlled chaos
 */


let cw, ch
let mushrooms = []
let BG_COLOR = '#000000'
let M_COLOR = BG_COLOR
let A_COLOR = '#ffffff'
let PALETTES = [
	["#f24358", "#f2a643", "#f2e343", "#43f278", "#43a0f2", "#c343f2"],
	['#0ad2ff', '#2962ff', '#9500ff', '#ff0059', '#ff8c00', '#b4e600', '#0fffdb'],
	["#0863d3", "#f5d216", "#f43809", "#08b233", "#9913bf"],
	["#4464a1", "#62b6de", "#b3dce0", "#ffc5c7", "#ee726b", "#cd1440"]
]
let PALETTE
let mushroomIndices = []
let grass = [], spores = []

function setup () {
  createCanvas(cw = 800, ch = 800)
  let nMushrooms = floor(random(4, 6))
  strokeCap(SQUARE)
  strokeJoin(BEVEL)
	PALETTE = random(PALETTES)
  mushroomIndices = shuffle([...new Array(nMushrooms).keys()])
  for (let i = 0; i < nMushrooms; i++) {
    let radiusX = random(50, 120)
    let index = mushroomIndices[i]
    mushrooms.push(new Mushroom({
      x: (cw * (i+1) / (nMushrooms + 1)) + random(-cw/10, cw/10),
      y: ch / 2,
      radiusX,
      radiusY: radiusX * random(0.4, 0.6),
      maxDist: 20,
      minDist: 0,
      nf: random(1, 2),
      squishFactor: 0.001 * random(1, 4),
      numPoints: floor(random(20, 30)),
      stemLength: radiusX * (random(1.2, 1.5) + ((nMushrooms - index) * 0.3)),
      growAnimFrames: random(50, 80)
    }))
  }
  let nGrassBlades = floor(random(40, 60))
  for (let i = 0; i < nGrassBlades; i++) {
    let x = random(cw * 0.1, cw * 0.9)
    let y = random(ch * 0.7, ch * 0.9)
    let blade = {
      x, y,
      height: random(50, 150),
      thickness: random(5, 15),
      sway: random(20, 40),
      swaySpeed: random(0.2, 0.5),
    }
    grass.push(blade)
  }
  grass.sort((a, b) => a.y - b.y)

  spores = {
    front: generateSpores(),
    back: generateSpores(),
  }

  frameRate(10)
}

function draw () {
  background(BG_COLOR)

  let groundY = ch * 0.7
  let grassBladesCopy = [...grass]

  for (let spore of spores.back) {
    drawAndUpdateSpore(spore)
  }

  for (let i = 0; i < mushrooms.length; i++) {
    let relativeY = map(i, 0, mushrooms.length - 1, 0, ch * 0.2)
    for (let j = grassBladesCopy.length - 1; j >= 0; j--) {
      let blade = grassBladesCopy[j]
      if (blade.y < groundY + relativeY + 20) {
        grassBladesCopy.splice(j, 1)
        drawGrassBlade(blade)
      }
    }

    let mush = mushrooms[mushroomIndices[i]]

    push()
    mush.grow()
    translate(mush.x, groundY - mush.stemLength)
    translate(0, relativeY)
    mush.draw()
    pop()
  }

  for (let spore of spores.front) {
    drawAndUpdateSpore(spore)
  }
}

class Mushroom {
  constructor (opts) {
    this.radiusX = opts.radiusX
    this.radiusY = opts.radiusY
    this._widthRatio = this.radiusX / this.radiusY
    this.maxDist = opts.maxDist
    this.minDist = opts.minDist
    this.nf = opts.nf
    this.squishFactor = opts.squishFactor
    this.numPoints = opts.numPoints
    this.stemLength = opts.stemLength
    this.x = opts.x
    this.y = opts.y
    this.skew = opts.skew || this.radiusX * random(0.1, 0.6)
    this._skewRatio = this.skew / this.radiusX

    this._origRadiusX = this.radiusX
    this.headRotation = random(-PI/10, PI/10)
    this.growAnimFrames = opts.growAnimFrames || 100
    this.stroke = new Stroke({
      cap: Stroke.Cap.SQUARE,
      join: Stroke.Join.BEVEL,
      closed: true,
    })
    this.color = opts.color || random(PALETTE)
    this.setupGrowth()
  }

  setupGrowth () {
    this.targetWidth = this.radiusX
    this.targetHeight = this.stemLength
    this.radiusX = this.targetWidth / random(3, 5)
    this.stemLength = this.targetHeight / random(3, 5)
    this.origRadiusX = this.radiusX
    this.origStemLength = this.stemLength
    this.growthFactor = 0.5

    this.animFrame = 0
  }

  draw () {
    this.drawHead()
    this.drawStem()
  }

  grow () {
    let growth = easeGrow(this.animFrame / this.growAnimFrames)
    this.radiusX = map(growth, 0, 1, this.origRadiusX, this.targetWidth)
    this.radiusY = this.radiusX / this._widthRatio
    this.skew = this.radiusX * this._skewRatio
    this.stemLength = map(growth, 0, 1, this.origStemLength, this.targetHeight)
    if (this.animFrame < this.growAnimFrames) {
      this.animFrame++
    } else {
      this._sf = this._sf || frameCount
      this.radiusX = this._origRadiusX * map(sin((frameCount - this._sf) * 0.2), -1, 1, 1, 1)
    }
  }

  drawHead () {
    push()
    rotate(this.headRotation)
    this.drawOuterHead()
    this.drawInnerHead()
    pop()
  }

  drawInnerHead () {
    let { radiusX, radiusY, maxDist, minDist, nf, squishFactor, numPoints } = this
    let points = getBlob(radiusX, radiusY, numPoints, minDist, maxDist, nf, squishFactor)
    points = segmentLine(points, 20)
    points = wiggle(points, 10, 2, true)
    let mesh = this.stroke.build(points, (point, i, points) => {
      return random(0.5, 10)
    })
    fill(M_COLOR)
    noStroke()

    drawPoints(points, true)
    drawMesh(mesh, () => {
      stroke(this.color)
      strokeWeight(1)
      fill(this.color)
    })

    for (let p of points) {
      let innerLine = [[0, 0], p]
      innerLine = segmentLine(innerLine, random(5, 15))
      innerLine = wiggle(innerLine, 5, 0.5, true)
      mesh = this.stroke.build(innerLine, (point, i, points) => {
        return map(i, 0, points.length, 0.5, 4)
      })
      drawMesh(mesh, (i, cells, ps) => {
        let alpha = floor(map(i, 0, cells.length * 7/8, 255, 0, true))
        let c = this.color + hex(alpha, 2)
        // console.log(c)
        fill(c)
        noStroke()
      })
    }
  }

  drawOuterHead () {
    let { radiusX, radiusY, maxDist, minDist, nf, squishFactor, numPoints } = this
    let points = getBlob(radiusX * 2, radiusY * 2, numPoints, minDist, maxDist, nf, squishFactor / 2)
    points = segmentLine(points, 20)
    points = wiggle(points, 5, 2, true)

    let nnf = 0.6
    let mesh = this.stroke.build(points, (point, i, points) => {
      let angle = map(i, 0, points.length, 0, TAU)
      let offX = cos(angle) + 1
      let offY = sin(angle) + 1
      let minRange = [this.radiusX * 0.05, this.radiusX * 0.1]
      let maxRange = [this.radiusX * 0.05, this.radiusX * 1.5]
      let n = 1 - (sin(angle) * 0.5 + 0.5)
      let min = map(n, 0, 1, minRange[0], minRange[1])
      let max = map(n, 0, 1, maxRange[0], maxRange[1])
      return map(noise(offX * nnf, offY * nnf), 0, 1, min, max)
    })

    fill(M_COLOR)
    noStroke()

    drawPoints(points, true)
    drawMesh(mesh, () => {
      strokeWeight(2)
      stroke(this.color)
      fill(this.color)
    })
  }

  _getStem () {
    let stemPoints = []
    let minSize = [this._origRadiusX * 0.2, this._origRadiusX * 0.4] //[30, 80]
    let maxSize = [this._origRadiusX * 0.5, this._origRadiusX * 1.2]

    this._f = this._f || random(1, 4)
    this._d = this._d || random([1, -1])
    if (!this._n) {
      this._n = 1
      if (random() < 0.3) {
        this._n = -1
        this._f = this._f * 2
      }
    }
    let ease = (x) => {
      if (this._n === 1) {
        return pow(x, this._f)
      } else {
        return 1 - pow(1 - x, this._f)
      }
    }
    for (let i = 0; i < this.stemLength; ) {
      if (i > this.stemLength) {
        i = this.stemLength
      }
      let f = ease(i / this.stemLength)
      let min = map(f, 0, 1, minSize[0], minSize[1])
      let max = map(f, 0, 1, maxSize[0], maxSize[1])
      let x = f * this.skew * this._d
      let w = map(
        noise((frameCount + i) * 0.01),
        0, 1,
        min, max
      ) + random(-3, 3)
      stemPoints.push({ y: i, x, w })
      i += map(i, 0, this.stemLength, 10, 2)
    }

    // Add bottom ellipse
    let cx = this.skew * this._d
    let cy = this.stemLength
    let r = stemPoints[stemPoints.length - 1].w / 2
    for (let a = PI; a > PI/2; a -= (PI / 20)) {
      if (a === PI) continue
      let x = cx + cos(a) * r
      let y = cy + sin(a) * 20
      stemPoints.push({
        x: cx,
        y,
        w: 2 * (cx - x),
      })
    }

    return stemPoints
  }

  drawStem () {
    let stemPoints = this._getStem()

    let stemShape = []
    stemShape = stemShape.concat(stemPoints.map(p => [p.x + -p.w / 2, p.y]))
    stemShape = stemShape.concat(stemPoints.map(p => [p.x + p.w / 2, p.y]).reverse())

    // Add top ellipse
    let r = stemPoints[0].w / 2
    for (let a = 0; a < PI; a += (Math.max(0.001, Math.abs((PI / 10)) || 1))) {
      if (a === 0) continue
      let s = r * this.skew / this.radiusX
      let x = cos(a) * r - (map(sin(a), 0, 1, 0, s)) * this._d
      let y = sin(a) * (-20)
      stemShape.push([x, y])
    }

    fill(M_COLOR)
    noStroke()
    drawPoints(stemShape, true)

    stroke(this.color)
    for (let i = 0; i < stemPoints.length; i++) {
      let p = stemPoints[i]
      let sw = map(p.y, 0, this.stemLength, 0.5, 2)
      strokeWeight(sw)
      let d = 2
      let d1 = random(-d, d)
      let d2 = random(-d, d)
      let start = p.x + -p.w / 2 + sw / 2
      let end = p.x + p.w / 2 - sw / 2
      line(
        start,
        p.y + d1,
        map(noise((frameCount * 0.3 + i) * 0.5), 0, 1, start, end),
        p.y + d2
      )
    }
    let mesh = this.stroke.build(stemShape, (point, i, points) => {
      return random(2, 5)
    })
    drawMesh(mesh, () => {
      stroke(this.color)
      strokeWeight(1)
      fill(this.color)
    })
  }
}

let drawGrassBlade = (leaf) => {
  push()
  noFill()
  translate(leaf.x, leaf.y)
  stroke(A_COLOR)
  strokeWeight(random(2, 3))
  let sway = leaf.sway + map(noise((frameCount * leaf.swaySpeed) + leaf.x), 0, 1, -leaf.sway/2, leaf.sway/2)
  let f = map(noise((frameCount * leaf.swaySpeed) + leaf.x), 0, 1, 2, 5)
  beginShape()
  curveVertex(-leaf.thickness / 2, 0)
  curveVertex(-leaf.thickness / 2, 0)
  let _resolution = 5
  for (let i = 0; i < _resolution; i++) {
    let p = map(i, 0, _resolution, 0, 1)
    let q = easeGrass(p, f)
    let nx = lerp(-leaf.thickness / 2, sway, q)
    let ny = lerp(0, -leaf.height, p)
    curveVertex(nx, ny)
  }
  curveVertex(sway, -leaf.height)
  for (let i = 0; i < _resolution; i++) {
    let p = map(i, 0, _resolution, 1, 0)
    let q = easeGrass(p, f)
    let nx = lerp(leaf.thickness / 2, sway, q)
    let ny = lerp(0, -leaf.height, p)
    curveVertex(nx, ny)
  }
  curveVertex(leaf.thickness / 2, 0)
  curveVertex(leaf.thickness / 2, 0)
  endShape()
  pop()
}

let generateSpores = () => {
  let spores = []
  for (let i = 0; i < 100; i++) {
    let x = random(cw)
    let y = random(ch * 0.85)
    let r = random(3, 12)
    spores.push({ x, y, r })
  }
  return spores
}

let drawAndUpdateSpore = (spore) => {
  let { x, y, r } = spore
  let speed = 1
  let angle = map(noise(x * 0.1, y * 0.2, frameCount * 0.08), 0, 1, 0, TAU)
  let dx = cos(angle) * speed
  let dy = sin(angle) * speed
  x += dx
  y += dy
  spore.x = x
  spore.y = y
  if (x < 0) x = cw
  if (x > cw) x = 0

  noStroke()
  fill(A_COLOR + hex(floor(random(50, 100)), 2))
  ellipse(x, y, r, r * map(noise(x * 0.1, y * 0.2, frameCount * 0.08), 0, 1, 0.5, 1.5))
  spore.x = x
  spore.y = y
}

let getBlob = (radiusX, radiusY, numPoints, minDist, maxDist, noiseFactor, squishFactor) => {
  let points = []
  let angle = 0
  let angleStep = TAU / numPoints
  let delta = random(10)
  for (let i = 0; i < numPoints; i++) {
    let xOff = cos(angle) + delta
    let yOff = sin(angle) + delta
    let x = cos(angle) * (radiusX + map(noise(xOff * noiseFactor, yOff * noiseFactor), 0, 1, minDist, maxDist))
    let y = sin(angle) * (radiusY + map(noise(xOff * noiseFactor, yOff * noiseFactor), 0, 1, minDist, maxDist))
    let topY = -radiusY
    let squishedY = y - (squishFactor * pow((topY - y), 2))
    points.push([x, squishedY])
    angle += angleStep
  }
  return points
}

let drawMesh = (mesh, styleFn) => {
  for (let i = 0; i < mesh.cells.length; i++) {
    let cell = mesh.cells[i]
    let v0 = mesh.positions[cell[0]],
      v1 = mesh.positions[cell[1]],
      v2 = mesh.positions[cell[2]]
    styleFn && styleFn(i, mesh.cells, [v0, v1, v2])
    triangle(v0.x, v0.y, v1.x, v1.y, v2.x, v2.y)
  }
}

let drawPoints = (points, closed = false) => {
  beginShape()
  for (let p of points) {
    vertex(...p)
  }
  endShape(closed ? CLOSE : null)
}

let wiggle = (points, d = 2, nf = 0.5, keepEdges) => {
  let wigglePoints = []
  for (let i = 0; i < points.length - 1; i++) {
    if (keepEdges && (i === 0)) {
      wigglePoints.push(points[i])
      continue
    }
    let p0 = points[i]
    let p1 = points[i + 1]
    let direction = [p1[0] - p0[0], p1[1] - p0[1]]
    let perpendicular = [-direction[1], direction[0]]
    let length = sqrt(perpendicular[0] ** 2 + perpendicular[1] ** 2)
    perpendicular = [perpendicular[0] / length, perpendicular[1] / length]
    let wiggle = map(noise(i * nf), 0, 1, -d, d)
    let wigglePoint = [p0[0] + perpendicular[0] * wiggle, p0[1] + perpendicular[1] * wiggle]
    wigglePoints.push(wigglePoint)
  }
  wigglePoints.push(points[points.length - 1])
  return wigglePoints
}

let segmentLine = (points, d) => {
  let segmentedPoints = [points[0]]

  for (let i = 0; i < points.length - 1; i++) {
    let p0 = points[i]
    let p1 = points[i + 1]
    let distance = dist(p0[0], p0[1], p1[0], p1[1])

    if (distance <= d) {
      segmentedPoints.push(p1)
    } else {
      let segments = ceil(distance / d)
      let deltaX = (p1[0] - p0[0]) / segments
      let deltaY = (p1[1] - p0[1]) / segments

      for (let j = 1; j <= segments; j++) {
        let x = p0[0] + j * deltaX
        let y = p0[1] + j * deltaY
        segmentedPoints.push([x, y])
      }
    }
  }
  return segmentedPoints
}

let ease = (x) => {
  return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
}

let easeGrass = (x, p) => {
  return pow(x, p)
}

let easeGrow = (x) => {
  const c1 = 1.70158
  const c3 = c1 + 1

  return 1 + c3 * pow(x - 1, 3) + c1 * pow(x - 1, 2)
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

